// El slot es de otro owner con lease vigente. Una tarea sin slot queda
// PENDIENTE, nunca fallida (17 §3). El reconciliador la retomará.
const x = $input.first().json;
return [{ json: { estado: 'en_cola', motivo: x.error ?? 'slot ocupado' } }];

// ARCHIVO GENERADO — no editar a mano.
// Fuente: ../runtime/nodos/decidir-paso.mjs (región CODE_NODE). Regenerar: node n8n/runtime/generar-code-nodes.mjs
// Worker: traduce el checkpoint a la rama de ESTA ejecución (17 §3).

const x = $input.first().json;
const TERMINALES = ['terminado', 'error', 'timeout'];
const cp = x.checkpoint ?? {};
const estado = cp.estado_interno ?? 'preparar_contexto';
const maxReparaciones = Number(x.max_reparaciones ?? 1);
const reparaciones = Number(cp.reparaciones_json ?? 0);
const pendientes = Array.isArray(cp.pending_tool_use_ids) ? cp.pending_tool_use_ids : [];
const ahora = Number(x.ahora_ms ?? Date.parse(x.ahora ?? new Date().toISOString()));
const limite = cp.deadline_at ? Date.parse(cp.deadline_at) : Number.POSITIVE_INFINITY;

const cerrar = (evento, razon) => ({
  accion: 'cerrar', evento, razon, motivo_request: null,
  estado_interno: estado, reparaciones_json: reparaciones,
});
const pedirModelo = (motivo, razon) => ({
  accion: 'solicitar_modelo', evento: null, razon, motivo_request: motivo,
  estado_interno: estado, reparaciones_json: reparaciones,
});

let salida;
if (TERMINALES.indexOf(estado) >= 0) {
  salida = cerrar(null, 'el paso ya estaba en estado terminal');
} else if (ahora >= limite) {
  // El deadline manda sobre cualquier otra rama: no se abre un request nuevo
  // que no cabe en el paso.
  salida = cerrar('deadline', 'deadline del paso alcanzado');
} else if (estado === 'preparar_contexto' || estado === 'solicitar_modelo') {
  salida = pedirModelo('turno', 'turno normal del protocolo');
} else if (estado === 'espera_reintento') {
  salida = pedirModelo('turno', 'reintento de transporte reprogramado por el dispatcher');
} else if (estado === 'reparar_json') {
  salida = reparaciones < maxReparaciones
    ? pedirModelo('reparacion', 'una reparación acotada, sin herramientas')
    : cerrar('sin_reparacion', 'sin presupuesto de reparación: error visible');
} else if (estado === 'ejecutar_herramienta') {
  salida = pendientes.length > 0
    ? {
      accion: 'ejecutar_herramienta', evento: null, motivo_request: null,
      razon: `${pendientes.length} tool_use pendiente(s)`,
      estado_interno: estado, reparaciones_json: reparaciones,
      pending_tool_use_ids: pendientes,
    }
    : cerrar('error_fatal', 'estado ejecutar_herramienta sin tool_use pendientes');
} else if (estado === 'validar_salida') {
  if (cp.salida_valida) salida = cerrar('valida', 'salida válida: el paso cierra');
  else if (reparaciones < maxReparaciones) salida = pedirModelo('reparacion', 'salida inválida con presupuesto de reparación');
  else salida = cerrar('sin_reparacion', 'salida inválida y sin reparación disponible');
} else {
  salida = cerrar('error_fatal', `estado interno no manejado: ${estado}`);
}
return [{ json: salida }];

// ARCHIVO GENERADO — no editar a mano.
// Fuente: ../runtime/nodos/construir-cuerpo.mjs (región CODE_NODE). Regenerar: node n8n/runtime/generar-code-nodes.mjs
// Worker: compone el body de /v1/messages con insumos de DB (17 §5.2).

const x = $input.first().json;
if (!x.modelo) throw new Error('modelo ausente: se resuelve de configuración, nunca del prompt');
if (!Array.isArray(x.system_bloques) || x.system_bloques.length === 0) {
  throw new Error('system ausente: bloque común + rol + contrato son obligatorios');
}
if (!Array.isArray(x.mensajes) || x.mensajes.length === 0) {
  throw new Error('mensajes ausentes: el checkpoint debe traer al menos el paquete de contexto');
}
// Todo tool_use del último assistant debe tener su tool_result en el
// siguiente user: compactar borrando pares rompe el protocolo (17 §7).
const ultimoAssistant = [...x.mensajes].reverse().find((m) => m.role === 'assistant');
if (ultimoAssistant) {
  const usos = (ultimoAssistant.content ?? []).filter((b) => b.type === 'tool_use').map((b) => b.id);
  if (usos.length > 0) {
    const indice = x.mensajes.lastIndexOf(ultimoAssistant);
    const siguiente = x.mensajes[indice + 1];
    const resueltos = ((siguiente && siguiente.content) || [])
      .filter((b) => b.type === 'tool_result').map((b) => b.tool_use_id);
    const faltantes = usos.filter((id) => resueltos.indexOf(id) < 0);
    if (faltantes.length > 0) throw new Error(`faltan tool_result para: ${faltantes.join(', ')}`);
  }
}
const cuerpo = {
  model: x.modelo,
  max_tokens: Number(x.max_tokens ?? 2000),
  temperature: x.temperatura === undefined || x.temperatura === null ? 0 : Number(x.temperatura),
  system: x.system_bloques,
  messages: x.mensajes,
};
const herramientas = Array.isArray(x.herramientas) ? x.herramientas : [];
// Reparación acotada y roles sin tools (Réplica, Redactor, Editor) no reciben
// la clave `tools` (17 §5.8).
if (x.sin_herramientas !== true && herramientas.length > 0) {
  cuerpo.tools = herramientas;
  cuerpo.tool_choice = { type: 'auto' };
}
const salida = { cuerpo, herramientas_enviadas: cuerpo.tools ? cuerpo.tools.length : 0 };
return [{ json: salida }];

// ARCHIVO GENERADO — no editar a mano.
// Fuente: ../runtime/nodos/clasificar-transporte.mjs (región CODE_NODE). Regenerar: node n8n/runtime/generar-code-nodes.mjs
// Worker: 429/5xx con Retry-After, timeout ambiguo (17 §6).

const x = $input.first().json;
const BASE_BACKOFF_MS = 500;
const MAX_BACKOFF_MS = 8000;
const MAX_REINTENTOS = Number(x.max_reintentos ?? 2);
const status = x.status === undefined ? null : x.status;
const tipo = x.tipo ?? null;
const intento = Number(x.intento ?? 1);
const ahora = Number(x.ahora_ms ?? Date.parse(x.ahora ?? new Date().toISOString()));
const limite = x.deadline_at ? Date.parse(x.deadline_at) : Number.POSITIVE_INFINITY;
const headers = x.headers ?? {};

let clase;
if (tipo === 'timeout' || tipo === 'conexion_interrumpida') clase = 'ambiguo';
else if (status === null) clase = 'error';
else if (status >= 200 && status < 300) clase = 'ok';
else if (status === 429 || status === 408 || status >= 500) clase = 'reintentable';
else clase = 'error';

const crudo = headers['retry-after'] ?? headers['Retry-After'] ?? null;
let segundos = null;
if (crudo !== null && crudo !== undefined && crudo !== '') {
  const numero = Number(crudo);
  if (Number.isFinite(numero)) segundos = numero;
  else {
    const fecha = Date.parse(String(crudo));
    if (Number.isFinite(fecha)) segundos = Math.max(0, (fecha - ahora) / 1000);
  }
}
const aleatorio = x.aleatorio === undefined || x.aleatorio === null ? Math.random() : Number(x.aleatorio);
const techo = Math.min(MAX_BACKOFF_MS, BASE_BACKOFF_MS * Math.pow(2, Math.max(0, intento - 1)));
const espera_ms = segundos !== null ? Math.max(0, Math.round(segundos * 1000)) : Math.round(techo * aleatorio);

const cabeEnDeadline = ahora + espera_ms < limite;
const reintentar = clase === 'reintentable' && intento <= MAX_REINTENTOS && cabeEnDeadline;
// Ruta EXCLUYENTE para el switch del workflow: una respuesta correcta no
// puede caer además en la rama de «desconocido».
let ruta;
if (clase === 'ok') ruta = 'continuar';
else if (reintentar) ruta = 'reintentar';
else if (clase === 'ambiguo') ruta = 'desconocido';
else ruta = 'error';
const salida = {
  clase,
  ruta,
  espera_ms: reintentar ? espera_ms : 0,
  intento,
  reintentar,
  retry_after_respetado: segundos !== null,
  motivo: clase === 'ambiguo'
    ? 'timeout_ambiguo: posible consumo externo sin respuesta; no se reintenta automáticamente'
    : clase === 'reintentable' && !reintentar
      ? (cabeEnDeadline ? 'reintentos_transporte_agotados' : 'deadline_excedido')
      : null,
};
return [{ json: salida }];

// ARCHIVO GENERADO — no editar a mano.
// Fuente: ../runtime/nodos/interpretar-respuesta.mjs (región CODE_NODE). Regenerar: node n8n/runtime/generar-code-nodes.mjs
// Worker: stop_reason, cola de tool_use y parseo de salida (17 §5.5–5.8).

const x = $input.first().json;
const REQUERIDAS = {
  documental: ['senal_ids', 'resumen', 'limitaciones'],
  financiero: ['senal_ids', 'resumen', 'limitaciones'],
  relacional: ['senal_ids', 'resumen', 'limitaciones'],
  temporal: ['senal_ids', 'resumen', 'limitaciones'],
  externo: ['senal_ids', 'resumen', 'limitaciones'],
  auditor: ['rfc_principal', 'rfcs_satelite', 'tipologia', 'hipotesis', 'evidencia', 'limitaciones'],
  defensor: ['argumentos'],
  replica: ['resoluciones'],
  redactor: ['markdown'],
  editor: [],
};
const CONTRATO = {
  documental: 'agents.especialista', financiero: 'agents.especialista',
  relacional: 'agents.especialista', temporal: 'agents.especialista',
  externo: 'agents.especialista', auditor: 'agents.auditor',
  defensor: 'agents.defensor', replica: 'agents.replica',
  redactor: 'agents.redactor', editor: 'agents.editor',
};
const rol = x.rol;
const cuerpo = (x.respuesta && x.respuesta.body) ? x.respuesta.body : (x.body ?? {});
const stop = cuerpo.stop_reason ?? null;
const bloques = Array.isArray(cuerpo.content) ? cuerpo.content : [];
const comun = {
  provider_request_id: cuerpo.id ?? null,
  usage: cuerpo.usage ?? null,
  modelo: cuerpo.model ?? null,
  stop_reason: stop,
  bloques_assistant: bloques,
  rol,
  contrato: CONTRATO[rol] ?? null,
  requiere_validacion_contrato: true,
};

let salida;
if (stop === 'tool_use') {
  const cola = bloques.filter((b) => b.type === 'tool_use')
    .map((b) => ({ tool_use_id: b.id, nombre: b.name, argumentos: b.input ?? {} }));
  salida = cola.length > 0
    ? Object.assign({}, comun, { tipo: 'tool_use', cola, evento: 'tool_use' })
    : Object.assign({}, comun, { tipo: 'json_invalido', evento: 'end_turn', cola: [], diagnostico: 'stop_reason=tool_use sin bloques tool_use' });
} else if (stop === 'max_tokens') {
  // Salida truncada: jamás se persiste como informe válido (17 §7).
  salida = Object.assign({}, comun, {
    tipo: 'incompleto', evento: 'max_tokens', salida_valida: null,
    texto: bloques.filter((b) => b.type === 'text').map((b) => b.text).join('\n'),
    diagnostico: 'salida truncada por max_tokens; no es un informe válido',
  });
} else if (stop === 'refusal') {
  salida = Object.assign({}, comun, { tipo: 'refusal', evento: 'refusal', diagnostico: 'el proveedor rechazó continuar' });
} else if (stop === 'end_turn' || stop === 'stop_sequence') {
  const texto = bloques.filter((b) => b.type === 'text').map((b) => b.text).join('\n').trim();
  const sinValla = texto.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  const candidatos = [sinValla];
  const abre = sinValla.indexOf('{');
  const cierra = sinValla.lastIndexOf('}');
  if (abre >= 0 && cierra > abre) candidatos.push(sinValla.slice(abre, cierra + 1));
  let valor = null;
  for (const candidato of candidatos) {
    try {
      const parsed = JSON.parse(candidato);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) { valor = parsed; break; }
    } catch (e) { /* siguiente candidato */ }
  }
  if (valor === null) {
    salida = Object.assign({}, comun, { tipo: 'json_invalido', evento: 'end_turn', texto, errores: [{ instancePath: '/', message: 'no se pudo parsear un objeto JSON' }] });
  } else {
    const requeridas = REQUERIDAS[rol] ?? [];
    const faltan = requeridas.filter((k) => valor[k] === undefined);
    const sobran = requeridas.length > 0 ? Object.keys(valor).filter((k) => requeridas.indexOf(k) < 0) : [];
    const errores = faltan.map((k) => ({ instancePath: `/${k}`, message: 'campo requerido ausente' }))
      .concat(sobran.map((k) => ({ instancePath: `/${k}`, message: 'campo no permitido por el contrato' })));
    salida = errores.length > 0
      ? Object.assign({}, comun, { tipo: 'schema_invalido', evento: 'end_turn', texto, salida: valor, errores })
      : Object.assign({}, comun, { tipo: 'salida_estructura_ok', evento: 'end_turn', salida: valor, errores: [] });
  }
} else {
  salida = Object.assign({}, comun, {
    tipo: 'stop_desconocido', evento: 'refusal',
    diagnostico: `stop_reason no soportada: ${String(stop)}`,
  });
}
return [{ json: salida }];

// Mismo tool_use_id ya ejecutado: se devuelve el resultado guardado.
// No consume cuota ni repite la mutación SQL (17 §6).
const x = $input.first().json;
return [{ json: { tool_use_id: x.tool_use_id, resultado: x.resultado, error: x.error ?? null, reentrega: true } }];

// ARCHIVO GENERADO — no editar a mano.
// Fuente: ../runtime/nodos/armar-tool-results.mjs (región CODE_NODE). Regenerar: node n8n/runtime/generar-code-nodes.mjs
// Worker: un tool_result por cada tool_use_id, en orden (17 §5.5).

const x = $input.first().json;
const cola = Array.isArray(x.cola) ? x.cola : [];
const resultados = Array.isArray(x.resultados) ? x.resultados : [];
if (cola.length === 0) throw new Error('cola de tool_use vacía: no hay resultados que enviar');
const porId = new Map(resultados.map((r) => [r.tool_use_id, r]));
const faltantes = cola.filter((t) => !porId.has(t.tool_use_id)).map((t) => t.tool_use_id);
if (faltantes.length > 0) throw new Error(`faltan tool_result para: ${faltantes.join(', ')}`);
const content = cola.map((t) => {
  const r = porId.get(t.tool_use_id);
  const esError = (r.error !== null && r.error !== undefined) || r.is_error === true;
  const payload = esError
    ? { ok: false, error: r.error ?? { codigo: 'error_herramienta', mensaje: 'error sin detalle', reintentable: false } }
    : r.resultado;
  const bloque = {
    type: 'tool_result',
    tool_use_id: t.tool_use_id,
    content: typeof payload === 'string' ? payload : JSON.stringify(payload),
  };
  if (esError) bloque.is_error = true;
  return bloque;
});
const salida = {
  mensaje: { role: 'user', content },
  tool_use_ids: cola.map((t) => t.tool_use_id),
  con_error: content.filter((b) => b.is_error === true).length,
};
return [{ json: salida }];
